/bin/zsh -lc "python3 -B -c '
from pathlib import Path
from contextlib import contextmanager
from copy import deepcopy
from itertools import permutations

namespace = {}
exec(compile(Path(\"project/consumer.py\").read_text(), \"project/consumer.py\", \"exec\"), namespace)
consume = namespace[\"consume\"]

class DB:
    def __init__(self):
        self.accounts = {}
        self.audit = []
        self.fail_audit = False
    @contextmanager
    def transaction(self):
        before = deepcopy((self.accounts, self.audit))
        try:
            yield
        except Exception:
            self.accounts, self.audit = before
            raise
    def set_account(self, account, revision, tier):
        self.accounts[account] = (revision, tier)
    def insert_audit(self, event_id):
        if self.fail_audit:
            raise RuntimeError(\"audit failed\")
        self.audit.append(event_id)

class Delivery:
    def __init__(self, fail_ack=False):
        self.acked = False
        self.fail_ack = fail_ack
    def ack(self):
        if self.fail_ack:
            raise RuntimeError(\"ACK outcome unknown\")
        self.acked = True

e12 = dict(event_id=\"e12\", account_id=\"a\", revision=12, tier=\"gold\")
e11 = dict(event_id=\"e11\", account_id=\"a\", revision=11, tier=\"silver\")
db = DB()
for event in (e12, e12, e11):
    consume(event, db, Delivery())
print(\"Actual consume, successful deliveries:\", db.accounts, db.audit)
assert db.accounts == {\"a\": (11, \"silver\")}
assert db.audit == [\"e12\", \"e12\", \"e11\"]

# Sequential model only: a real DB must make this predicate and write atomic.
def proposed(event, db, delivery):
    with db.transaction():
        current = db.accounts.get(event[\"account_id\"])
        if current is None or event[\"revision\"] > current[0]:
            db.set_account(event[\"account_id\"], event[\"revision\"], event[\"tier\"])
            db.insert_audit(event[\"event_id\"])
    delivery.ack()

db = DB()
for event in (e12, e12, e11):
    proposed(event, db, Delivery())
assert db.accounts == {\"a\": (12, \"gold\")} and db.audit == [\"e12\"]
print(\"Revision-guard model, supplied history:\", db.accounts, db.audit)

for history in permutations((e12, e12, e11)):
    db = DB()
    for event in history:
        proposed(event, db, Delivery())
    assert db.accounts == {\"a\": (12, \"gold\")}
    assert db.audit.count(\"e12\") == 1
    assert db.audit.count(\"e11\") == (history[0][\"revision\"] == 11)
print(\"PASS: all six permutations; audit follows snapshots actually applied\")

db = DB()
try:
    proposed(e12, db, Delivery(fail_ack=True))
except RuntimeError:
    pass
proposed(e12, db, Delivery())
assert db.accounts == {\"a\": (12, \"gold\")} and db.audit == [\"e12\"]
print(\"PASS: commit then lost ACK then redelivery produces one audit\")

db = DB()
db.fail_audit = True
delivery = Delivery()
try:
    proposed(e12, db, delivery)
except RuntimeError:
    pass
assert db.accounts == {} and db.audit == [] and not delivery.acked
db.fail_audit = False
proposed(e12, db, Delivery())
assert db.accounts == {\"a\": (12, \"gold\")} and db.audit == [\"e12\"]
print(\"PASS: audit failure rolls back state, no ACK, retry succeeds\")

db = DB()
delivery = Delivery()
try:
    consume(dict(event_id=\"bad\", account_id=\"a\", revision=13), db, delivery)
except KeyError as error:
    assert db.accounts == {} and db.audit == [] and not delivery.acked
    print(\"Actual consume, missing tier:\", type(error).__name__, \"with no ACK or quarantine\")
'"

